const base = $('Execute Workflow Trigger').first().json;
const inputItems = $input.all();

let patients = [];

if (inputItems.length === 1 && Array.isArray(inputItems[0].json)) {
  patients = inputItems[0].json;
} else {
  patients = inputItems
    .map(item => item.json)
    .filter(p => p && typeof p === 'object' && p.id && p.full_name);
}

const session      = base.session ?? {};
const pendingCtx   = session.pending_context ?? {};
const step         = session.current_step ?? 'idle';
const interactive  = base.message?.interactive ?? {};
const text         = String(base.message?.text ?? '').trim();
const forceList    = base._pm_force_list === true;
const pmMode       = pendingCtx.pm_mode ?? null;

const normalize = (v) =>
  String(v ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim()
    .replace(/\s+/g, ' ');

const normalizedText = normalize(text);
const isInt = (v) => /^\d+$/.test(String(v ?? '').trim());

const newWords = [
  'nuevo', 'nueva', 'agregar', 'registrar',
  'otro', 'otra', 'nuevo paciente', 'paciente nuevo'
];

const wantsNew = newWords.includes(normalizedText);

const build = (patch = {}) => ({
  json: {
    ...base,
    _patients: patients,
    ...patch,
  }
});

const exactMatches = normalizedText
  ? patients.filter(p => normalize(p.full_name) === normalizedText)
  : [];

const partialMatches = normalizedText
  ? patients.filter(p => normalize(p.full_name).includes(normalizedText))
  : [];

// 0) Si estamos esperando el nombre de un paciente NUEVO,
// entonces crear directamente y no reinterpretar como selección/lista
if (step === 'awaiting_patient_name' && pmMode === 'creating_new_patient' && text.length > 0) {
  return [build({
    _pm_action: 'create_patient',
    _new_name: text
  })];
}

// 1) Entrada inicial desde catálogo:
// NO interpretar el texto actual como selección de paciente
if (forceList) {
  if (patients.length >= 1) {
    return [build({ _pm_action: 'show_list' })];
  }

  return [build({ _pm_action: 'ask_name' })];
}

// 2) Botones directos
if (interactive.id?.startsWith('CF:PAT:') && interactive.id !== 'CF:PAT:start') {
  const patientId = interactive.id.replace('CF:PAT:', '');
  const patient = patients.find(p => p.id === patientId) ?? null;

  if (patient) {
    return [build({ _pm_action: 'select_existing', _patient: patient })];
  }

  return [build({ _pm_action: 'show_list', _pm_error: 'patient_not_found' })];
}

if (interactive.id === 'CF:NEWPAT') {
  return [build({ _pm_action: 'ask_name' })];
}

// 3) Selección por número cuando ya hay lista mostrada
if (step === 'select_patient' && isInt(text)) {
  const idx = Number(text) - 1;
  const patient = idx >= 0 && idx < patients.length ? patients[idx] : null;

  if (patient) {
    return [build({ _pm_action: 'select_existing', _patient: patient })];
  }

  return [build({ _pm_action: 'show_list', _pm_error: 'invalid_selection' })];
}

// 4) Si explícitamente quiere registrar uno nuevo
if (wantsNew) {
  return [build({ _pm_action: 'ask_name' })];
}

// 5) Coincidencia exacta única
if (exactMatches.length === 1) {
  return [build({ _pm_action: 'select_existing', _patient: exactMatches[0] })];
}

// 6) Coincidencia exacta ambigua
if (exactMatches.length > 1) {
  return [build({
    _pm_action: 'show_list',
    _candidate_name: text || null,
    _pm_error: 'ambiguous_exact_match'
  })];
}

// 7) Coincidencia parcial única
if (partialMatches.length === 1) {
  return [build({ _pm_action: 'select_existing', _patient: partialMatches[0] })];
}

// 8) Coincidencia parcial ambigua
if (partialMatches.length > 1) {
  return [build({
    _pm_action: 'show_list',
    _candidate_name: text || null,
    _pm_error: 'ambiguous_partial_match'
  })];
}

// 9) Si hay varios pacientes, mostrar lista
if (patients.length > 1) {
  return [build({
    _pm_action: 'show_list',
    _candidate_name: text || null
  })];
}

// 10) Si hay uno solo, seleccionarlo
if (patients.length === 1) {
  return [build({ _pm_action: 'select_existing', _patient: patients[0] })];
}

// 11) Si no hay pacientes
if (patients.length === 0) {
  if (step === 'awaiting_patient_name' && text.length > 0) {
    return [build({ _pm_action: 'create_patient', _new_name: text })];
  }

  return [build({ _pm_action: 'ask_name' })];
}

// 12) Fallback
return [build({ _pm_action: 'show_list' })];

const base         = $('Evaluar pacientes').first().json;
const action       = base._pm_action ?? null;
const session      = base.session ?? {};
const patientState = base.patient ?? {};
const currentStep  = session.current_step ?? 'idle';
const activeServiceId = session.active_service_id ?? null;
const existingCtx  = session.pending_context ?? {};

const allInputItems = $input.all();

const buildSessionUpdate = (patch = {}) => ({
  ...patch,
});

const safePatients = Array.isArray(base._patients) ? base._patients : [];

const makeText = (body) => ({
  type: 'text',
  body,
});

const firstValidCreatedPatient = () => {
  for (const item of allInputItems) {
    const raw = item?.json;

    if (Array.isArray(raw)) {
      const found = raw.find(p => p && typeof p === 'object' && p.id && p.full_name);
      if (found) return found;
    }

    if (raw && typeof raw === 'object' && raw.id && raw.full_name) {
      return raw;
    }
  }
  return null;
};

let patient = null;

if (action === 'select_existing') {
  patient = base._patient ?? null;
} else if (action === 'create_patient') {
  patient = firstValidCreatedPatient();
}

// ── 1) Pedir nombre ─────────────────────────────────────────────────
if (action === 'ask_name') {
  return [{
    json: {
      ...base,
      session: {
        ...session,
        current_step: 'awaiting_patient_name',
        pending_context: {
          ...existingCtx,
          pm_mode: 'creating_new_patient',
        },
      },
      _session_update: buildSessionUpdate({
        current_step: 'awaiting_patient_name',
        pending_context: {
          ...existingCtx,
          pm_mode: 'creating_new_patient',
        },
      }),
      _advance_to: 'outbound',
      _outbound: makeText(
        '👤 ¿A nombre de quién agendamos la cita?\n\nEscribe el nombre completo del paciente.'
      ),
    }
  }];
}

// ── 2) Mostrar lista de pacientes ───────────────────────────────────
if (action === 'show_list') {
  if (safePatients.length === 0) {
    return [{
      json: {
        ...base,
        session: {
          ...session,
          current_step: 'awaiting_patient_name',
        },
        _session_update: buildSessionUpdate({
          current_step: 'awaiting_patient_name',
          pending_context: {
            ...existingCtx,
          },
        }),
        _advance_to: 'outbound',
        _outbound: makeText(
          '👤 No encontré pacientes registrados con este número.\n\nEscribe el nombre completo del paciente para registrarlo.'
        ),
      }
    }];
  }

  const list = safePatients
    .slice(0, 10)
    .map((p, i) => `*${i + 1}.* ${p.full_name}`)
    .join('\n');

  const extraHint =
    safePatients.length > 10
      ? '\n\n_Mostré los primeros 10 resultados. Responde con el número correspondiente o escribe *nuevo*._'
      : '\n\nResponde con el número del paciente o escribe *nuevo* para registrar otro.';

  return [{
    json: {
      ...base,
      session: {
        ...session,
        current_step: 'select_patient',
      },
      _session_update: buildSessionUpdate({
        current_step: 'select_patient',
        pending_context: {
          ...existingCtx,
        },
      }),
      _advance_to: 'outbound',
      _outbound: makeText(
        '👤 ¿Para quién agendamos la cita?\n\n' +
        list +
        extraHint
      ),
    }
  }];
}

// ── 3) Paciente resuelto correctamente ──────────────────────────────
if (patient?.id) {
  const cleanedCtx = { ...existingCtx };
  delete cleanedCtx.pm_mode;

  const nextStep  = activeServiceId ? 'select_slot' : 'select_service';
  const advanceTo = activeServiceId ? 'availability' : 'catalog_engine';

  return [{
    json: {
      ...base,
      patient: {
        ...patientState,
        active_patient_id: patient.id,
      },
      session: {
        ...session,
        current_step: nextStep,
        active_patient_id: patient.id,
        pending_slot_start: null,
        pending_slot_end: null,
        pending_context: cleanedCtx,
      },
      _session_update: buildSessionUpdate({
        current_step: nextStep,
        active_patient_id: patient.id,
        pending_slot_start: null,
        pending_slot_end: null,
        pending_context: cleanedCtx,
      }),
      _advance_to: advanceTo,
    }
  }];
}

// ── 4) Fallback de create_patient fallido ───────────────────────────
if (action === 'create_patient') {
  return [{
    json: {
      ...base,
      session: {
        ...session,
        current_step: 'awaiting_patient_name',
      },
      _session_update: buildSessionUpdate({
        current_step: 'awaiting_patient_name',
        pending_context: {
          ...existingCtx,
        },
      }),
      _advance_to: 'outbound',
      _outbound: makeText(
        '⚠️ No pude registrar al paciente.\n\nEscribe nuevamente el nombre completo.'
      ),
    }
  }];
}

// ── 5) Fallback general ─────────────────────────────────────────────
return [{
  json: {
    ...base,
    _advance_to: 'outbound',
    _outbound: makeText(
      '⚠️ No pude identificar al paciente correctamente.\n\nEscribe *hola* para reiniciar.'
    ),
  }
}];

