// Supabase PATCH devuelve {} vacío — recuperar desde Build Respuesta PM
const e = $('Build Respuesta PM').item.json;
return [{ json: {
  ...e,
  _patients:       undefined,
  _patient:        undefined,
  _pm_action:      undefined,
  _session_update: undefined,
  _new_name:       undefined
}}];

// Pre-filtro NLP: detectar si _new_name necesita extracción inteligente
const e      = $input.first().json;
const action = e._pm_action ?? '';
const name   = String(e._new_name ?? '').trim();

// Solo activar cuando vamos a crear paciente y el texto parece compuesto
if (action !== 'create_patient' || !name) {
  return [{ json: { ...e, _needs_name_nlp: false } }];
}

// Patrones que indican que el usuario no escribió solo el nombre
const contextPatterns = [
  /\b(para|mi|es para|soy|se llama|le llama|de nombre|nombre es|llamo|llamar|llama)\b/i,
  /\b(mamá|mama|papá|papa|hijo|hija|niño|niña|bebé|bebe|abuela|abuelo|esposo|esposa|pareja|hermano|hermana|sobrino|sobrina)\b/i,
  /^(el|la|un|una|es|soy|para)\s/i
];

const wordCount       = name.split(/\s+/).filter(Boolean).length;
const hasContextWords = contextPatterns.some(p => p.test(name));

// Activar NLP si: > 3 palabras, O contiene palabras de contexto
const needsNlp = wordCount > 3 || hasContextWords;

return [{ json: { ...e, _needs_name_nlp: needsNlp, _raw_patient_text: name } }];

// Construir prompt para extracción de nombre de paciente
const envelope = $input.first().json;
const text     = String(envelope._raw_patient_text ?? envelope.message?.text ?? '').trim();
const clinic   = envelope.tenant?.name ?? 'la clínica';

const system =
  `Eres un asistente médico de ${clinic}. ` +
  `El usuario está registrando a un paciente para una cita. ` +
  `Extrae el nombre propio de la persona del mensaje. ` +
  `Ignora palabras de contexto como "para", "mi", "mamá", "hijo", etc. ` +
  `Capitaliza correctamente (Primera letra mayúscula por palabra). ` +
  `Responde ÚNICAMENTE con JSON sin texto adicional:\n` +
  `{"name": "Nombre Apellido", "confidence": 0.0}\n` +
  `Si el texto no contiene un nombre claro, usa null en "name".`;

const user = `Mensaje: "${text}"`;

return [{ json: {
  ...envelope,
  _groq_messages: [{ role: 'system', content: system }, { role: 'user', content: user }]
} }];

// Parsear respuesta GROQ y actualizar _new_name con nombre limpio
const envelope = $('Build GROQ Prompt — Nombre').first().json;
const groqResp = $input.first().json;

let extractedName = null;
let confidence    = 0;

try {
  const content = String(groqResp?.choices?.[0]?.message?.content ?? '');
  const cleaned = content.replace(/```json|```/g, '').trim();
  const parsed  = JSON.parse(cleaned);
  extractedName = parsed?.name ?? null;
  confidence    = Number(parsed?.confidence ?? 0);
} catch (_) { /* GROQ no disponible */ }

// Validar: nombre razonable (2-50 chars, no vacío, confianza mínima)
const isValid = extractedName &&
                typeof extractedName === 'string' &&
                extractedName.trim().length >= 2 &&
                extractedName.trim().length <= 60 &&
                confidence >= 0.65;

const finalName = isValid
  ? extractedName.trim()
  : envelope._raw_patient_text;  // fallback: usar texto original

return [{
  json: {
    ...envelope,
    _new_name:            finalName,
    _groq_messages:       undefined,
    _needs_name_nlp:      false,
    _raw_patient_text:    undefined,
    _nlp_extracted_name:  isValid ? finalName : null,  // debug
  }
}];
